 "content": "from collections import deque


def transform(grid):
    """Color the largest and smallest 4-connected zero regions 8 and 7."""
    h, w = len(grid), len(grid[0])
    seen = set()
    regions = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 0 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            regions.append(cells)
    if len(regions) < 2:
        return [row[:] for row in grid]
    smallest = min(regions, key=len)
    largest = max(regions, key=len)
    out = [row[:] for row in grid]
    for r, c in smallest:
        out[r][c] = 7
    for r, c in largest:
        out[r][c] = 8
    return out
